from pathlib import Path
import base64
import datetime
import shutil
import py_compile

ROOT = Path.cwd()

if not (ROOT / "backend" / "labtwin").exists():
    raise SystemExit("Run this script from the LabTwin-AI project root.")

payload = {
    'backend/labtwin/views.py': '',
    'backend/labtwin/memory_views.py': '',
    'frontend/src/App.jsx': '',
}

timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
backup_root = ROOT / ("accuracy_backup_" + timestamp)
backup_root.mkdir(parents=True, exist_ok=True)

for relative_path, encoded in payload.items():
    target = ROOT / relative_path
    if not target.exists():
        raise SystemExit(f"Required file not found: {target}")
    backup = backup_root / relative_path
    backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(target, backup)

print(f"Backup folder: {backup_root}")

for relative_path, encoded in payload.items():
    target = ROOT / relative_path
    target.write_bytes(base64.b64decode(encoded))
    print(f"Updated: {relative_path}")

py_compile.compile(str(ROOT / "backend/labtwin/views.py"), doraise=True)
py_compile.compile(str(ROOT / "backend/labtwin/memory_views.py"), doraise=True)

print("LABTWIN V2 ACCURACY FIX SUCCESS")
print("No database migration is required.")